34	constexpr const char *kDeviceAttr = "device";
35	
36	#define GEN_PASS_DEF_CONSTANTOPDEVICEASSIGNMENTPASS
37	#include "tensorflow/compiler/mlir/tensorflow/transforms/tf_passes.h.inc"
38	
39	struct ConstantOpDeviceAssignmentPass
40	    : public impl::ConstantOpDeviceAssignmentPassBase<
41	          ConstantOpDeviceAssignmentPass> {
42	  void runOnOperation() override;
43	};
44	
45	void ConstantOpDeviceAssignmentPass::runOnOperation() {
46	  ModuleOp module = getOperation();
47	
48	  module.walk([&](TF::ConstOp op) {
49	    // Keep the ConstOp if the op already have the device attribute.
50	    if (StringAttr device_attr = op->getAttrOfType<StringAttr>(kDeviceAttr)) {
51	      return WalkResult::advance();
52	    }
53	    OpBuilder builder(op);
54	    llvm::StringMap<mlir::Operation *> cloned_op_by_device;
55	    bool all_uses_replaced = true;
56	
57	    for (mlir::OpOperand &use :
58	         llvm::make_early_inc_range(op.getResult().getUses())) {
59	      mlir::Operation *user_op = use.getOwner();
60	      StringAttr device_attr = user_op->getAttrOfType<StringAttr>(kDeviceAttr);
61	      if (!device_attr) {
62	        all_uses_replaced = false;
63	        continue;
64	      }
65	      // Cloned the ConstOp and set its device attribute to be the same as the
66	      // device of the user operation.
67	      if (cloned_op_by_device.find(device_attr.getValue()) ==
68	          cloned_op_by_device.end()) {
69	        mlir::Operation *new_op = builder.clone(*op.getOperation());
70	        new_op->setAttr(kDeviceAttr, device_attr);
71	        cloned_op_by_device[device_attr.getValue()] = new_op;
72	      }
73	      // Update the user operation to use the result of the cloned ConstOp.
74	      mlir::Operation *new_op = cloned_op_by_device[device_attr.getValue()];
75	      user_op->setOperand(use.getOperandNumber(), new_op->getResult(0));
76	    }
77	    // Erase the original ConstOp if all its uses have been replaced.
78	    if (all_uses_replaced) {
79	      op.erase();
80	    }
81	    return WalkResult::advance();
82	  });
83	}
84	
85	}  // namespace
86	
87	std::unique_ptr<OperationPass<ModuleOp>>
88	CreateConstantOpDeviceAssignmentPass() {
89	  return std::make_unique<ConstantOpDeviceAssignmentPass>();
90	}
91	
92	}  // namespace TF
93	}  // namespace mlir
