114	// Dumps the MLIR module to disk.
115	// This require the TF_DUMP_GRAPH_PREFIX to be set to a path that exist (or can
116	// be created).
117	static void DumpModule(mlir::ModuleOp module, std::string file_prefix) {
118	  std::string prefix = GetDumpDirFromEnvVar();
119	  if (prefix.empty()) return;
120	
121	  auto* env = tensorflow::Env::Default();
122	  auto status = env->RecursivelyCreateDir(prefix);
123	  if (!status.ok()) {
124	    LOG(WARNING) << "cannot create directory '" << prefix
125	                 << "': " << status.message();
126	    return;
127	  }
128	
129	  prefix += "/" + file_prefix;
130	  if (!tensorflow::Env::Default()->CreateUniqueFileName(&prefix, ".mlir")) {
131	    LOG(WARNING) << "cannot create unique filename, won't dump MLIR module.";
132	    return;
133	  }
134	
135	  std::unique_ptr<WritableFile> file_writer;
136	  status = env->NewWritableFile(prefix, &file_writer);
137	  if (!status.ok()) {
138	    LOG(WARNING) << "cannot open file '" << prefix << "': " << status.message();
139	    return;
140	  }
141	
142	  // Print the module to a string before writing to the file.
143	  std::string txt_module;
144	  {
145	    llvm::raw_string_ostream os(txt_module);
146	    module.print(os);
147	  }
148	
149	  status = file_writer->Append(txt_module);
150	  if (!status.ok()) {
151	    LOG(WARNING) << "error writing to file '" << prefix
152	                 << "': " << status.message();
153	    return;
154	  }
155	  (void)file_writer->Close();
156	  VLOG(1) << "Dumped MLIR module to " << prefix;
157	}
